/// <summary>
/// Data contract class for sales picking list generation service task
/// </summary>
[DataContractAttribute]
class METSalesPickingListGenerationTaskContract
{
    container       oscCodeList;
    SalesId         salesId, csdSalesId;
    utcdatetime     csdOrderExtractDateTime; //CB123 - SalesOrderExtractScreenforCSD
    int             csdSalesOrderCount;

}

Method.Source:
    /// <summary>
    /// OSCCode list which contains the list of OSCCode need to be processed
    /// </summary>
    /// <param name = "_oscCodeList">OSCCode list</param>
    /// <returns>OSCCode list</returns>
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
    public container parmOSCCodeList(container _oscCodeList = oscCodeList)
    {
        oscCodeList = _oscCodeList;

        return oscCodeList;
    }

    /// CB123 - SalesOrderExtractScreenforCSD
    /// <summary>
    /// CSD Sales Id which need to be processed
    /// </summary>
    /// <param name = "_csdSalesId">CSD Sales Id</param>
    /// <returns>CSD Sales Id</returns>
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
    public SalesId parmCSDSalesId(SalesId _csdSalesId = csdSalesId)
    {
        csdSalesId = _csdSalesId;

        return csdSalesId;
    }

    /// <summary>
    /// Sales Id which need to be processed
    /// </summary>
    /// <param name = "_salesId">Sales Id</param>
    /// <returns>Sales Id</returns>
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
    public SalesId parmSalesId(SalesId _salesId = salesId)
    {
        salesId = _salesId;

        return salesId;
    }

    /// CB123 - SalesOrderExtractScreenforCSD
    /// <summary>
    /// CSD sales order extract start date time
    /// </summary>
    /// <param name = "_csdOrderExtractDateTime">Extract start date time</param>
    /// <returns>Sales order extract start date time</returns>
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
    public utcdatetime parmCSDSalesOrderExtractDateTime(utcdatetime _csdOrderExtractDateTime = csdOrderExtractDateTime)
    {
        csdOrderExtractDateTime = _csdOrderExtractDateTime;

        return csdOrderExtractDateTime;
    }

    /// <summary>
    /// get Caption for the batch job task based on sales id and OSC code
    /// </summary>
    /// <returns>batch job caption</returns>
    public str getCaption()
    {
        int i;
        str caption = strFmt('%1 - ', this.parmSalesId());

        for(i = 1; i <= conLen(this.parmOSCCodeList()); i++)
        {
            if(i != 1)
            {
                caption += ', ';                
            }
            caption += conPeek(this.parmOSCCodeList(), i);
        }
        return caption;
    }

    /// <summary>
    /// Captures csd sales order count
    /// </summary>
    /// <param name = "_csdSalesOrderCount">csd sales order count</param>
    /// <returns>csdSalesOrderCount</returns>
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
    public int parmCSDSalesOrderCount(int _csdSalesOrderCount = csdSalesOrderCount)
    {
        csdSalesOrderCount = _csdSalesOrderCount;

        return csdSalesOrderCount;
    }
